"use strict";
// esbuild's `--format=cjs` bundle shape, verbatim down to the minifier's
// spelling — this is what zapo's `spec/proto/index.js` is, reduced to three
// modules instead of nineteen.
//
// `r` is esbuild's `__commonJS`: it takes a one-entry object literal whose
// KEY is the module's path (a string literal) and whose VALUE is the module
// body written as a SHORTHAND METHOD, and returns a memoizing thunk.
// `o(e)[0]` reads that single key back out, `(0, e[k])(...)` calls the body
// indirectly (so `this` is undefined), and `t` caches the module record so
// the body runs exactly once no matter how many times the thunk is called.
var o = Object.getOwnPropertyNames,
  r = (e, t) =>
    function () {
      return t || (0, e[o(e)[0]])(((t = { exports: {} }).exports), t), t.exports;
    };

// The preamble binds getOwnPropertyNames; `Object.keys` is its near twin
// (the same own-key walk, differing only over the index-keyed kinds — see
// `family` below), so bind it the same way and drive it. The lift covers
// exactly this pair and nothing should claim coverage it does not have:
// `Object.values`/`entries` are declared GENERIC and refuse at the
// generic-method-as-value rule instead, which is a different rule's
// frontier and deliberately not driven here.
var k = Object.keys;

// module 1: `t.exports = <function>` (the aspromise.js shape)
var a = r({
  "node_modules/tiny/zigzag.js"(e, t) {
    sideEffects.push("zigzag");
    t.exports = function (v) {
      return ((v << 1) ^ (v >> 31)) >>> 0;
    };
  },
});

// module 2: `e.<member> = v` onto the exports object (the base64.js shape),
// and it REQUIRES module 1 through the thunk.
var s = r({
  "node_modules/tiny/varint.js"(e) {
    sideEffects.push("varint");
    var t = e;
    t.write = function (out, v) {
      var n = a()(v);
      while (n > 127) {
        out.push((n & 127) | 128);
        n = n >>> 7;
      }
      out.push(n & 127);
      return out;
    };
    t.tag = function (id, wire) {
      return (id << 3) | wire;
    };
  },
});

// module 3: one body reached through BOTH the other two — proves the thunk
// memoizes rather than re-running the method.
var c = r({
  "node_modules/tiny/index.js"(e, t) {
    sideEffects.push("index");
    var n = s();
    t.exports = {
      encodeField: function (id, v) {
        var out = [];
        n.write(out, n.tag(id, 0));
        n.write(out, v);
        return out;
      },
      names: function () {
        return o({ alpha: 1, beta: 2 }).join(",");
      },
      // The twin, read through a SECOND module-scope binding from inside a
      // module body the thunk reaches. And the pair over receivers where
      // the two walks DIVERGE: an array and a string carry `length` as an
      // OWN property, so getOwnPropertyNames lists it and keys does not —
      // folding one onto the other was a wrong byte, and this drives it
      // both ways against Node.
      family: function () {
        return (
          k({ alpha: 1, beta: "two" }).join(",") +
          "|" + k(["x", "y", "z"]).join(",") +
          "|" + o(["x", "y", "z"]).join(",") +
          "|" + o("ab").join(",") +
          "|" + o(new Uint8Array([7, 8])).join(",")
        );
      },
    };
  },
});

// module 4: the word `this`, and nothing else. A module body written as an
// object-literal METHOD gets no receiver, so a `this` that is lexically the
// METHOD's has to stay fenced — but every `this` HERE belongs to a plain
// function EXPRESSION the body declares, which resets `this` in JavaScript
// and reaches the ambient receiver the compiler already lowers
// (lowerExpr's ThisKeyword arm -> `dyn.this`).
//
// The whole-body walk used to refuse the whole module for them. On zapo's
// shipped `spec/proto/index.js` that one walk took down NINE of the
// nineteen bundled modules — reader, writer, longbits, util/minimal,
// long/umd, eventemitter, the two buffer variants and rpc/service, 27 519
// of the 34 111 bytes of protobufjs the bundle carries — and an AST census
// of all nineteen found ZERO methods whose `this` is lexically the
// method's. Every one is inside `function Writer() { this.len = 0 }`.
//
// Deliberately NOT driven here: `X.prototype.m = v` and `new X` are
// separate unclosed families (property assignment on a function value, and
// constructing a non-program class), so a `Writer` written the way
// protobufjs writes it would measure them instead of this. The dispatch
// below is dyn OBJ method dispatch, which binds the receiver box, so a
// wrong `this` shows up as a wrong BYTE here and not as a fence.
var w = r({
  "node_modules/tiny/writer.js"(e, t) {
    sideEffects.push("writer");
    var api = {
      len: 0,
      bump: function (n) {
        this.len = this.len + n;
        return this.len;
      },
      kind: function () {
        return typeof this.bump;
      },
    };
    t.exports = api;
  },
});

var sideEffects = [];

module.exports = {
  encodeField: function (id, v) {
    return c().encodeField(id, v);
  },
  names: function () {
    return c().names();
  },
  family: function () {
    return c().family();
  },
  // the `this`-inside-a-module-body walk, driven end to end: the receiver
  // is read, written and re-read through two members of the same object.
  writer: function (vals) {
    var api = w();
    var seen = [];
    for (var i = 0; i < vals.length; i++) seen.push(api.bump(vals[i]));
    return seen.join(",") + "|" + api.len + "|" + api.kind();
  },
  // the memoization witness: each module body appends its name ONCE
  order: function () {
    return sideEffects.join(">");
  },
};
